// Exercise the production timing popup; all writes/submissions are offline stubs.
async page => {
  const origin = new URL(page.url()).origin;
  if (!/^http:\/\/127\.0\.0\.1:\d+$/.test(origin)) throw new Error('Use first_use_server');
  const assert = (condition, message) => { if (!condition) throw new Error(message); };
  const errors = [], results = [];
  const onError = error => errors.push(error.message);
  page.on('pageerror', onError);
  await page.route(/^https?:\/\/(?!127\.0\.0\.1[:/])/, route => route.fulfill({ status: 200, contentType: 'text/css', body: '' }));
  try {
    for (const [width, language, theme] of [[1100, 'en', 'dark'], [390, 'ko', 'light'], [320, 'ru', 'dark']]) {
      await page.setViewportSize({ width, height: 840 });
      await page.goto(`${origin}/?surface=toolbar&language=${language}&theme=${theme}`);
      await page.evaluate(() => {
        ReactDOM.unmountComponentAtNode(document.getElementById('toolbar'));
        window.videoShareWrites = []; window.videoShareSubmissions = [];
        window.ivLyrics_firstLyricTime = 10000;
        Utils.updateSelectedVideoSyncOffset = async (uri, info) => window.videoShareWrites.push({ uri, ...info });
        Utils.submitCommunityVideo = (...args) => {
          window.videoShareSubmissions.push(args);
          return new Promise(resolve => { window.videoShareRelease = () => resolve({ success: true }); });
        };
        window.ivLyricsActiveCommunityVideoInfo = { trackUri: track.uri, youtubeVideoId: 'user-video-a',
          youtubeTitle: 'Applied video A', captionStartTime: 0, isAutoGenerated: true,
          skipSegments: [{ start: 1, end: 2 }], playerReady: true, videoDurationSeconds: 120 };
        ReactDOM.render(React.createElement(React.Fragment, null, React.createElement(IvLyricsFloatingToolbar, {
          actions: {}, isFullscreen: false, isMenuOpen: true, isMenuClosing: false, modeKey: 'synced',
          hasLyrics: true, hasSynced: true, hasKaraoke: false, karaokeEnabled: true,
          isLyricsLoading: false, trackUri: track.uri, syncTrackUri: track.uri,
          trackTitle: track.name, trackArtist: 'Fixture', lyrics,
        }), React.createElement('div', { id: 'video-share-quick', className: 'lyrics-quick-sync-stack' },
          React.createElement(TrackSyncAdjustPill, { trackUri: track.uri, videoTrackUri: track.uri }))), document.getElementById('toolbar'));
      });
      const videoLabel = await page.evaluate(() => I18n.t('videoSync.title'));
      await page.locator('#video-share-quick').getByRole('button', { name: videoLabel, exact: true }).click();
      await page.locator('.ivl-tb-item[data-entry="sync"]').click();
      const panel = page.locator('[data-section="video-sync"]');
      const label = await page.evaluate(() => I18n.t('videoSync.share'));
      const share = panel.getByRole('button', { name: label, exact: true });
      assert(await share.isDisabled(), 'an unedited automatic guess cannot be shared');
      await panel.getByRole('button', { name: /\+1s$/ }).click();
      await panel.getByRole('button', { name: /\+10ms$/ }).click();
      await page.waitForFunction(() => window.videoShareWrites.length > 0);
      assert(await share.isEnabled(), 'a local edit enables the explicit share action');
      assert(await page.evaluate(() => window.videoShareSubmissions.length) === 0, 'steps must not auto-submit');
      assert((await panel.textContent()).includes('11.010s'), 'the popup shows the exact current video anchor');
      await share.focus();
      await page.keyboard.press('Enter');
      await page.waitForFunction(() => window.videoShareSubmissions.length === 1);
      assert(await share.isDisabled() && await share.getAttribute('aria-busy') === 'true', 'in-flight share is visibly disabled');
      const quickShare = page.locator('#video-share-quick .lyrics-track-sync-share');
      assert(await quickShare.isDisabled(), 'the other surface observes the same pending contribution');
      await quickShare.evaluate(button => button.click());
      await share.evaluate(button => button.click());
      assert(await page.evaluate(() => window.videoShareSubmissions.length) === 1, 'disabled double click cannot submit twice');
      await page.evaluate(() => {
        window.ivLyricsActiveCommunityVideoInfo = { trackUri: track.uri, youtubeVideoId: 'user-video-b',
          youtubeTitle: 'Applied video B', captionStartTime: 29, isAutoGenerated: false,
          skipSegments: [], playerReady: true, videoDurationSeconds: 120 };
        window.dispatchEvent(new CustomEvent('ivLyrics:communityVideoChanged', { detail: { trackUri: track.uri } }));
        window.videoShareRelease();
      });
      await page.waitForFunction(() => document.querySelector('.ivl-tb-video-sync-share')?.disabled === false);
      const first = await page.evaluate(() => window.videoShareSubmissions[0]);
      assert(first[0] === 'spotify:track:fixture' && first[1] === 'user-video-a' && first[2] === 'Applied video A'
        && Math.abs(first[3] - 11.01) < .00001 && first[4][0].end === 2, 'auth cannot retarget the captured video contribution');
      await panel.getByRole('button', { name: /\+100ms$/ }).click();
      assert(await page.evaluate(() => window.videoShareSubmissions.length) === 1, 'replacement-video edits also stay local');
      await share.click();
      await page.waitForFunction(() => window.videoShareSubmissions.length === 2);
      const second = await page.evaluate(() => { window.videoShareRelease(); return window.videoShareSubmissions[1]; });
      assert(second[1] === 'user-video-b' && second[2] === 'Applied video B' && Math.abs(second[3] - 29.1) < .00001,
        'the second click shares only the newly applied video');
      await page.waitForFunction(() => document.querySelector('.ivl-tb-video-sync-share')?.disabled === false);
      const layout = await share.evaluate(button => {
        const header = button.closest('.ivl-tb-offset-header').getBoundingClientRect(), rect = button.getBoundingClientRect();
        return { left: rect.left, right: rect.right, top: rect.top, bottom: rect.bottom,
          fits: rect.left >= header.left - 1 && rect.right <= header.right + 1 && rect.left >= 0 && rect.right <= innerWidth };
      });
      assert(layout.fits, `share button is clipped: ${JSON.stringify(layout)}`);
      await page.screenshot({ path: `output/playwright/video-sync-share-${width}-${language}.png` });
      await page.evaluate(() => {
        window.ivLyricsActiveCommunityVideoInfo = null;
        window.dispatchEvent(new CustomEvent('ivLyrics:communityVideoChanged', { detail: { trackUri: track.uri } }));
      });
      await page.waitForFunction(() => !document.querySelector('[data-section="video-sync"]'));
      results.push({ width, language, theme, automaticSubmissions: 0, explicitSubmissions: 2, layout });
    }
    assert(errors.length === 0, JSON.stringify(errors));
    return { results, errors };
  } finally { page.off('pageerror', onError); }
}
